/* Independent design prototype. Fixture reads only; review state stays in this tab. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,restoreFocus,toastTimer,arrivalFrame,arrivalVersion=0;
const linkIcon='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m6 10 4-4M5.5 6.5l-1 1a2.8 2.8 0 0 0 4 4l1-1M6.5 5.5l1-1a2.8 2.8 0 0 1 4 4l-1 1"/></svg>';
const checkIcon='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 8 3 3 6-6"/></svg>';
const reducedMotion=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
const state={layer:0,file:'0',lastFile:'0',expanded:true,viewed:new Set(),seen:new Set(),summary:'0-49',complexity:'All',focus:false,focusPosition:null,mode:'unified',tab:'summaries',showResolved:false,thread:false,commentLine:null,codeRange:null,draft:'',savedDraft:'',emptyDemo:false,fullFile:true,collapsed:false};
const currentFile=()=>state.layer===0?data.files.find(f=>f.id===state.file):null;
const currentSummary=()=>currentFile()?.summaries.find(s=>s.id===state.summary);
function dismissToast(){clearTimeout(toastTimer);$('#toast').hidden=true}
function scheduleToast(){clearTimeout(toastTimer);if($('#toast').contains(document.activeElement)||$('#toast').matches(':hover'))return;toastTimer=setTimeout(dismissToast,8000)}
function toast(t,undo){const el=$('#toast');clearTimeout(toastTimer);el.innerHTML=`<span>${esc(t)}</span>${undo?'<button type="button">Undo</button>':''}`;el.hidden=false;if(undo)el.querySelector('button').onclick=()=>{undo();dismissToast();currentFile()?.lines?$('#viewed').focus():$('.layer.selected')?.focus()};scheduleToast()}
$('#toast').addEventListener('focusin',()=>clearTimeout(toastTimer));
$('#toast').addEventListener('mouseenter',()=>clearTimeout(toastTimer));
$('#toast').addEventListener('focusout',scheduleToast);
$('#toast').addEventListener('mouseleave',scheduleToast);
function updateViewedButton(){const f=currentFile(),viewed=!!f&&state.viewed.has(f.id);$('#viewed').innerHTML=viewed?checkIcon+'<span>Viewed</span>':'Mark viewed';$('#viewed').setAttribute('aria-pressed',String(viewed))}
function openDialog(title,html){restoreFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog').classList.remove('is-confirmed');$('#dialog').showModal()}
$('#dialog').addEventListener('close',()=>{if(restoreFocus?.isConnected)restoreFocus.focus();else $('#submit-review').focus()});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function renderNav(){
 $('#layer-list').innerHTML=data.layers.map((l,i)=>`<div class="layer-group"><button class="layer ${i===state.layer?'selected':''}" data-layer="${i}" aria-expanded="${i===state.layer&&state.expanded}" ${i===state.layer?'aria-current="true"':''}><span class="layer-number">${i+1}</span><span class="layer-copy"><strong>${esc(l.name)}</strong><small>${l.files} files${l.findings?' · '+l.findings+' finding'+(l.findings===1?'':'s'):''}</small></span><svg class="chevron" viewBox="0 0 16 16" aria-hidden="true"><path d="m6 4 4 4-4 4"/></svg></button>${i===state.layer&&state.expanded?`<div class="layer-files">${i===0?`<button class="file-nav" data-file="${state.file}" aria-current="true"><span class="viewed-box ${state.viewed.has(state.file)?'is-viewed':''}" aria-hidden="true"></span><span>${esc(currentFile().name)}</span></button><button class="text-link more-files" data-action="files">8 more files · open file list</button>`:'<p class="source-gap">File inventory is outside this focused prototype.</p>'}</div>`:''}</div>`).join('');
 $('#progress').textContent=`${state.viewed.size} / 52 files viewed`;
}
function setLayer(n){state.layer=Math.max(0,Math.min(6,n));state.expanded=true;if(state.layer===0)state.file=state.lastFile;state.summary=currentFile()?.summaries[0]?.id||null;state.complexity='All';state.collapsed=false;state.thread=false;state.commentLine=null;state.codeRange=null;renderScreen();if(currentSummary())scrollToLine(currentSummary().start,false)}
function selectFile(id){const f=data.files.find(x=>x.id===id);if(!f)return;state.layer=0;state.file=id;state.lastFile=id;state.expanded=true;state.summary=f.summaries[0]?.id||null;state.complexity='All';state.collapsed=false;state.thread=false;state.commentLine=null;state.codeRange=null;state.emptyDemo=false;renderScreen();$('#diff').scrollTop=0;if(currentSummary())scrollToLine(currentSummary().start,false)}
function renderScreen(){
 const l=data.layers[state.layer],f=currentFile();renderNav();$('#layer-title').textContent=l.name;$('#layer-position').textContent=`Layer ${state.layer+1} of 7`;
 $('#layer-description>p').textContent=l.description;$('#layer-meta').textContent=`${l.files} files${l.summaryCount?' · '+l.summaryCount+' layer summaries':''} · snapshot 23cdac2`;
 $('.file-toolbar').hidden=!f;$('#diff-status').hidden=!f;$('#diff').hidden=!f;$('#unavailable').hidden=!!f;
 if(f){$('.file-path').textContent=f.path.split('/').slice(0,-1).join(' / ');$('.file-path').title=f.path;$('.filename strong').textContent=f.name;$('.add-count').textContent='+'+f.added;$('.del-count').textContent='−'+f.deleted;$('#file-position').textContent=`${Number(f.id)+1} / 9`;$('#viewed').disabled=!f.lines;updateViewedButton();renderDiff()}
 $('#summaries-tab span').textContent=f?f.summaries.length:'—';$('#comments-tab span').textContent=f?f.comments:(l.comments??'—');
 $('#summary-progress').textContent=state.layer===0?`${state.seen.size} / 37 summaries seen · local`:'No summary fixture for this layer';
 $('.context-hint').textContent=f?`${f.summaries.length} of ${f.summaryCount} file summaries · ${l.summaryCount} in this layer`:'Layer metadata captured; detailed content is outside this prototype.';
 $('.context-footnote').textContent='Summaries condensed from the exact run. Uncaptured low-complexity summaries remain a labeled preview.';
 $('#complexity-controls').hidden=!f;renderSummaries();renderComments();
}
function renderSummaries(){
 const f=currentFile(),list=$('#summary-list'),items=(f?.summaries||[]).filter(s=>state.complexity==='All'||s.complexity===state.complexity),active=document.activeElement?.dataset,restore=active?.summary||active?.seen;
 list.innerHTML=items.length?items.map(s=>`<div class="summary-card"><button class="summary-item" data-summary="${s.id}" aria-pressed="${state.summary===s.id}"><span class="range">Lines ${s.range} · ${s.complexity}</span><strong>${esc(s.title)}</strong><span class="summary-body">${esc(s.body)}</span>${state.summary===s.id?`<span class="summary-linked">${linkIcon}Linked to code</span>`:''}</button><button class="summary-seen text-link" data-seen="${s.id}" aria-pressed="${state.seen.has(s.id)}">${state.seen.has(s.id)?'Seen · undo':'Mark seen'}</button></div>`).join(''):`<div class="empty-state"><h3>${f?'No captured '+state.complexity.toLowerCase()+' summaries':'No summary fixture'}</h3><p>This is a coverage limit, not a claim that the source has no summaries.</p></div>`;
 if(restore)$(`#summary-list [data-${active?.seen?'seen':'summary'}="${restore}"]`)?.focus();
 $$('#complexity-controls button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.complexity===state.complexity)));
}
function codeLine(text,n,side){const s=currentSummary(),selected=state.codeRange?n>=state.codeRange[0]&&n<=state.codeRange[1]:s&&n>=s.start&&n<=s.end;if(side==='old')return '<div class="code-row empty-row" aria-hidden="true"></div>';return `<div class="code-row add ${selected?'selected-code':''}" data-line="${n}"><span class="line-num" aria-label="Old line none"></span><span class="line-num" aria-label="New line ${n}">${n}</span><span class="diff-sign" aria-hidden="true">+</span><code>${esc(text)}</code><button class="comment-entry" data-comment-line="${n}" aria-label="Add local comment at line ${n}" title="Add local comment">+</button></div>`}
function renderDiff(){
 cancelAnimationFrame(arrivalFrame);arrivalVersion++;const f=currentFile(),el=$('#diff'),top=el.scrollTop,left=el.scrollLeft;if(!f)return;const range=state.codeRange||[currentSummary()?.start,currentSummary()?.end];$('#diff-status').hidden=false;$('#diff-status').innerHTML=`<span>${f.lines?'New file':'Modified file'} · +${f.added} −${f.deleted} · 23cdac2</span>${range[0]?`<span class="linked-range">${linkIcon}Linked · L${range[0]}–${range[1]}</span>`:''}`;
 if(!f.lines){el.innerHTML='<div class="unavailable"><h3>This modified-file diff is outside the fixture</h3><p>Its path and change counts were verified. A patch is not reconstructed from the full file.</p><button class="primary" data-file="0">Return to access.ts</button></div>';return}
 if(state.collapsed){el.innerHTML='<div class="code-note">File diff collapsed. <button class="text-link" data-action="expand-file">Show diff</button></div>';return}
 let rows=[],gapStart=null;for(let i=0;i<f.lines.length;i++){const n=i+1,show=state.fullFile||f.summaries.some(s=>n>=s.start&&n<=s.end);if(!show){gapStart??=n;continue}if(gapStart!==null){rows.push({gap:`${gapStart}–${n-1} outside captured summary ranges`});gapStart=null}rows.push({n,text:f.lines[i]})}if(gapStart!==null)rows.push({gap:`${gapStart}–${f.lines.length} outside captured summary ranges`});
 const content=state.mode==='split'?`<div class="split-label"><span>Before · file did not exist</span><span>After · pinned source</span></div>${rows.map(r=>r.gap?`<div class="hunk">${r.gap}</div>`:`<div class="split-pair"><div class="split-cell">${codeLine(r.text,r.n,'old')}</div><div class="split-cell">${codeLine(r.text,r.n,'new')}</div></div>`).join('')}`:rows.map(r=>r.gap?`<div class="hunk">${r.gap}</div>`:codeLine(r.text,r.n)).join('');
 el.innerHTML=`<div class="diff-content ${state.mode==='split'?'is-split':''}">${content}<div class="code-note">Pinned, out-of-date review snapshot. Resolved historical findings do not establish a current defect. Source: Formbricks; see the included source license.</div></div>`;
 el.scrollTop=top;el.scrollLeft=left;$('#unified').setAttribute('aria-pressed',String(state.mode==='unified'));$('#split').setAttribute('aria-pressed',String(state.mode==='split'));
}
function scrollToLine(n,smooth=true,emphasize=false){
 cancelAnimationFrame(arrivalFrame);const version=++arrivalVersion,el=$('#diff'),target=$(`#diff [data-line="${n}"]`);if(!target)return;
 const top=Math.max(0,Math.min(target.getBoundingClientRect().top-el.getBoundingClientRect().top+el.scrollTop-8,el.scrollHeight-el.clientHeight)),animate=smooth&&!reducedMotion();
 el.scrollTo({top,left:0,behavior:animate?'smooth':'instant'});
 if(!emphasize||reducedMotion())return;
 const started=performance.now();let stable=0,last=el.scrollTop;
 function arrive(){if(version!==arrivalVersion||!target.isConnected)return;const now=el.scrollTop;stable=Math.abs(now-last)<.5?stable+1:0;last=now;if(Math.abs(now-top)<1&&stable>1){target.classList.add('range-arrival');target.addEventListener('animationend',()=>target.classList.remove('range-arrival'),{once:true});return}if(performance.now()-started<1800)arrivalFrame=requestAnimationFrame(arrive)}
 arrivalFrame=requestAnimationFrame(arrive);
}
function selectSummary(id){const s=currentFile()?.summaries.find(x=>x.id===id);if(!s)return;state.summary=id;state.commentLine=null;state.codeRange=null;state.collapsed=false;renderSummaries();renderDiff();scrollToLine(s.start,true,true);$('#interaction-status').textContent=`${s.title}. Linked code, lines ${s.range}.`}
function toggleFocus(){const el=$('#diff'),position={top:el.scrollTop,left:el.scrollLeft};if(!state.focus)state.focusPosition=position;state.focus=!state.focus;document.body.classList.toggle('focus-mode',state.focus);$('#focus').setAttribute('aria-pressed',String(state.focus));$('#focus').innerHTML=`${state.focus?'Exit focus':'Focus'} <kbd>Z</kbd>`;const keep=state.focus?position:state.focusPosition;requestAnimationFrame(()=>el.scrollTo({...keep,behavior:'instant'}))}
function toggleViewed(){const f=currentFile();if(!f?.lines)return;const wasViewed=state.viewed.has(f.id);wasViewed?state.viewed.delete(f.id):state.viewed.add(f.id);renderNav();updateViewedButton();toast(`${f.name} ${wasViewed?'marked unviewed':'marked viewed'}`,()=>{wasViewed?state.viewed.add(f.id):state.viewed.delete(f.id);renderNav();updateViewedButton();$('#interaction-status').textContent=`Undone. ${f.name} ${wasViewed?'viewed':'unviewed'}.`})}
function setTab(name){
 state.tab=name;
 for(const n of ['summaries','comments']){const yes=n===name;$(`#${n}-tab`).setAttribute('aria-selected',String(yes));$(`#${n}-tab`).tabIndex=yes?0:-1;$(`#${n}-panel`).hidden=!yes}
 const previousRange=state.codeRange?.join('-');
 state.codeRange=name==='comments'?(state.commentLine?[state.commentLine,state.commentLine]:state.thread&&state.showResolved&&currentFile()?.id==='0'?[75,90]:null):null;
 if(previousRange!==state.codeRange?.join('-')){renderDiff();const start=state.codeRange?.[0]||currentSummary()?.start;if(start)scrollToLine(start,false)}
 if(name==='comments')renderComments();
}
function openContext(){if(state.focus)toggleFocus();$('#context').classList.add('is-open');$('#context-toggle').setAttribute('aria-expanded','true')}
function renderComments(){
 const f=currentFile(),el=$('#comments-panel');
 if(state.commentLine){el.innerHTML=`<div class="comment-thread"><h3>Local note · line ${state.commentLine}</h3><p>This draft belongs to the prototype and is never sent.</p>${state.savedDraft?`<p><strong>Saved in this tab</strong><br>${esc(state.savedDraft)}</p>`:''}<label for="comment-draft">Local draft</label><textarea id="comment-draft">${esc(state.draft)}</textarea><button class="primary" data-action="save-draft">Save local draft</button></div>`;return}
 if(state.emptyDemo||f?.comments===0){el.innerHTML=`<div class="empty-state"><h3>No comments to show</h3><p>${state.emptyDemo?'Labeled no-comments demonstration.':'No comment messages were shown for this file in the captured inventory.'}</p>${state.emptyDemo?'<button class="text-link" data-action="reset-empty">Return to source comments</button>':''}</div>`;return}
 if(!f){el.innerHTML='<div class="empty-state"><h3>Comments outside fixture</h3><p>The layer count may be captured, but no thread content is reproduced here.</p></div>';return}
 if(!state.showResolved){el.innerHTML=`<div class="empty-state"><h3>No matching comments</h3><p>${f.comments} resolved comment messages are hidden. Filters can hide comments even when the file has comments.</p><button data-action="show-resolved">Show resolved comments</button></div>`;return}
 if(f.id!=='0'){el.innerHTML=`<div class="empty-state"><h3>${f.comments} resolved messages in the source</h3><p>The count is verified; thread bodies for this file are outside the focused fixture.</p><button class="text-link" data-action="hide-resolved">Hide resolved comments</button></div>`;return}
 const t=data.thread;el.innerHTML=`<div class="source-filter"><span>Resolved messages shown</span><button class="text-link" data-action="hide-resolved">Hide</button></div><button class="thread-summary" data-action="open-thread"><strong>${esc(t.title)}</strong><small>${t.author} · ${t.severity} · Resolved · R${t.start}–${t.end}</small><span class="text-link">${state.thread?'Thread open':'Open historical thread'}</span></button>${state.thread?`<div class="comment-thread"><h3>Resolved source finding</h3><p>${esc(t.body)}</p><p class="small">Two reply bodies are not reproduced. Source resolution can be newer than the pinned code.</p><button class="text-link" data-comment-line="75">Add a local review note</button></div>`:''}`;
}
function showFiles(){openDialog('Files in layer 1',`<p>Nine verified file paths. Seven added-file diffs are included; two modified-file patches remain outside the fixture.</p><label for="file-search">Filter this layer’s files</label><input id="file-search" type="search" placeholder="Search nine verified paths"><div id="file-picker">${data.files.map(f=>`<button class="file-choice" data-file="${f.id}" data-path="${esc(f.path.toLowerCase())}"><span>${esc(f.path)}</span><small>${f.lines?'Added · +'+f.added:'Modified · patch not captured'}${state.viewed.has(f.id)?' · Viewed':''}</small></button>`).join('')}</div><div class="dialog-actions"><button value="cancel">Close</button></div>`)}
function showReview(){openDialog('Submit review',`<p>Review Formbricks #8650. This is a simulation; nothing is sent to GitHub or CodeRabbit.</p><p class="small">${state.viewed.size} of 52 files marked viewed locally. Seven file diffs are included. Summary seen is tracked separately.</p><fieldset><legend>Review decision</legend>${[['comment','Comment','Share feedback without a decision.'],['approve','Approve','Approve the pull request.'],['changes','Request changes','Ask for changes before merging.']].map(([v,t,d],i)=>`<label class="decision"><input type="radio" name="decision" value="${v}" ${i?'':'checked'}><span><strong>${t}</strong><small>${d}</small></span></label>`).join('')}</fieldset><div class="dialog-actions"><button value="cancel">Cancel</button><button class="primary" id="simulate-submit" type="button">Simulate submission</button></div>`)}
function confirmReview(){const value=$('input[name=decision]:checked').value,label=value==='approve'?'Approval':value==='changes'?'Request for changes':'Comment review';$('#dialog').classList.add('is-confirmed');$('#dialog-title').innerHTML=`<span class="confirmation-check">${checkIcon}</span>Review simulated`;$('#dialog-content').innerHTML=`<div class="confirmation-body"><p>${label} simulated.</p><p>Nothing was sent to GitHub or CodeRabbit.</p></div><div class="dialog-actions"><button value="return" id="return-review">Return to review</button></div>`;$('#return-review').focus()}
function showNotes(){openDialog('Source & prototype limits',`<p>Formbricks #8650 at the <a href="${esc(data.source.url)}" target="_blank" rel="noopener">assigned review run</a>, commit 23cdac2. This snapshot is out of date.</p><p>Seven of 52 file diffs are included. All seven layer names/counts and nine layer-1 paths were captured. Fourteen summaries are condensed; one resolved thread is paraphrased. Other content is labeled as preview.</p><div class="state-buttons"><button type="button" data-demo="loading">Loading state</button><button type="button" data-demo="unavailable">Source rate-limit state</button><button type="button" data-demo="empty">No-comments state</button><button type="button" data-demo="reset">Reset demo</button></div><p class="small">Review decisions and drafts stay in this tab; reload resets them. Nothing is sent. <a href="FORMBRICKS-LICENSE.txt" target="_blank" rel="noopener">Formbricks source license</a></p><div class="dialog-actions"><button value="cancel">Close</button></div>`)}
function preview(name){const descriptions={Overview:'Feedback records MCP integration · 52 files, seven layers. The selected review snapshot is out of date at 23cdac2. No live mergeability status is inferred.','Architecture impact':'The source exposes Security architecture impact. Its analysis was not captured; this is a placement preview.','Review history':'The captured source labels this review snapshot Stale / Out of date at commit 23cdac2. No other review history entries are fabricated.',Settings:'The source exposes display settings. Unified/Split and Full file are demonstrated; other preferences remain previews.','Low complexity':'Low-complexity summaries exist in the source, but their complete ranges were not captured. They are not counted as absent. Automatic follow-code and uncaptured summary controls remain placement previews.'};if(name==='Search pull request'){showFiles();return}if(!descriptions[name]){showNotes();return}openDialog(name,`<p>${descriptions[name]}</p><p class="small">Captured source or clearly labeled supporting preview. No external action.</p><div class="dialog-actions"><button value="cancel">Return to review</button></div>`)}
function showTools(){const f=currentFile();openDialog('File tools',`<p>Controls below operate on included fixture content. Diagram and automatic follow-code workflows are placement previews; the source diagram control was disabled.</p><div class="state-buttons"><button type="button" data-action="full-file">${state.fullFile?'Show captured ranges only':'Show full added file'}</button><button type="button" data-action="collapse-file">Collapse current diff</button><button type="button" data-action="bulk-viewed">Mark 7 included files viewed</button></div><h3>Captured semantic outline</h3><p class="small">${f?.summaries.length||0} of ${f?.summaryCount||0} summary ranges for this file.</p>${(f?.summaries||[]).map(s=>`<button class="file-choice" data-summary="${s.id}">${esc(s.title)} · ${s.range}</button>`).join('')}<div class="dialog-actions"><button value="cancel">Return to review</button></div>`)}
function loadingDemo(){selectFile('0');$('#diff-status').hidden=true;$('#diff').innerHTML='<div class="skeleton" aria-busy="true" aria-label="Loading file"><span></span><span></span><span></span><span></span></div><div class="code-note">Loading-state preview. Normal navigation has no artificial delay.<br><button class="text-link" id="restore-excerpt">Load pinned source</button></div>'}
function unavailableDemo(){openDialog('Observed source error',`<p>The live review initially loaded, but layer 2 later reported “Layer diff did not load.” Public repository checks were temporarily rate limited.</p><p>This is distinct from files intentionally outside the prototype fixture.</p><div class="dialog-actions"><button value="cancel">Return to pinned fixture</button><button type="button" id="retry-source">Retry source preview</button></div><p id="retry-result" role="status"></p>`)}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;if(b.id==='retry-data'){loadData();return}if(!data)return;
 if(b.dataset.layer!==undefined){const n=Number(b.dataset.layer);if(n===state.layer){state.expanded=!state.expanded;renderNav()}else setLayer(n);return}
 if(b.dataset.file!==undefined){if($('#dialog').open)$('#dialog').close();selectFile(b.dataset.file);return}
 if(b.dataset.summary){if($('#dialog').open)$('#dialog').close();selectSummary(b.dataset.summary);return}
 if(b.dataset.seen){state.seen.has(b.dataset.seen)?state.seen.delete(b.dataset.seen):state.seen.add(b.dataset.seen);renderSummaries();$('#summary-progress').textContent=`${state.seen.size} / 37 summaries seen · local`;toast('Summary progress updated. File viewed and review decision are unchanged.');return}
 if(b.dataset.complexity){if(b.dataset.complexity==='Low'){preview('Low complexity');return}state.complexity=b.dataset.complexity;const first=currentFile()?.summaries.find(s=>state.complexity==='All'||s.complexity===state.complexity);if(first)selectSummary(first.id);else renderSummaries();return}
 if(b.dataset.preview){preview(b.dataset.preview);return}
 if(b.dataset.commentLine){state.commentLine=Number(b.dataset.commentLine);state.codeRange=[state.commentLine,state.commentLine];state.emptyDemo=false;state.collapsed=false;renderDiff();openContext();setTab('comments');$('#comment-draft').focus();return}
 if(b.dataset.demo){$('#dialog').close();const a=b.dataset.demo;if(a==='loading')loadingDemo();if(a==='unavailable')unavailableDemo();if(a==='empty'){selectFile('0');state.emptyDemo=true;state.commentLine=null;setTab('comments');openContext()}if(a==='reset'){state.viewed.clear();state.seen.clear();state.showResolved=false;state.draft='';state.savedDraft='';state.emptyDemo=false;if(state.focus)toggleFocus();state.mode='unified';state.fullFile=true;selectFile('0');setTab('summaries')}return}
 switch(b.dataset.action){case 'overview':e.preventDefault();preview('Overview');return;case 'files':showFiles();return;case 'show-resolved':state.showResolved=true;renderComments();return;case 'hide-resolved':state.showResolved=false;state.thread=false;setTab('comments');return;case 'open-thread':state.thread=true;state.codeRange=[75,90];renderDiff();scrollToLine(75);renderComments();return;case 'save-draft':state.savedDraft=state.draft;toast('Draft saved in this tab. Nothing was sent.');return;case 'reset-empty':state.emptyDemo=false;renderComments();return;case 'full-file':state.fullFile=!state.fullFile;$('#dialog').close();renderDiff();if(currentSummary())scrollToLine(currentSummary().start,false);return;case 'collapse-file':state.collapsed=true;$('#dialog').close();renderDiff();return;case 'expand-file':state.collapsed=false;renderDiff();return;case 'bulk-viewed':data.files.filter(f=>f.lines).forEach(f=>state.viewed.add(f.id));$('#dialog').close();renderScreen();toast('Seven included files marked viewed locally; 45 other files remain unviewed.');return;}
 switch(b.id){case 'submit-review':showReview();break;case 'simulate-submit':confirmReview();break;case 'notes':showNotes();break;case 'return-file':selectFile('0');break;case 'viewed':toggleViewed();break;case 'focus':toggleFocus();break;case 'unified':case 'split':state.mode=b.id;renderDiff();break;case 'summaries-tab':setTab('summaries');break;case 'comments-tab':setTab('comments');break;case 'context-toggle':openContext();break;case 'close-context':$('#context').classList.remove('is-open');$('#context-toggle').setAttribute('aria-expanded','false');$('#context-toggle').focus();break;case 'summary-toggle':{const show=b.getAttribute('aria-expanded')==='false';b.setAttribute('aria-expanded',String(show));$('#layer-description').hidden=!show;$('.layer-heading').classList.toggle('is-collapsed',!show);b.firstChild.textContent=show?'Hide summary ':'Show summary ';break}case 'file-tools':showTools();break;case 'retry-source':$('#retry-result').textContent='Retry demonstration: live availability can vary. The pinned fixture remains available locally; no review was sent.';break;case 'restore-excerpt':renderDiff();break;}
});
document.addEventListener('input',e=>{if(e.target.id==='comment-draft')state.draft=e.target.value;if(e.target.id==='file-search')$$('.file-choice[data-path]').forEach(b=>b.hidden=!b.dataset.path.includes(e.target.value.toLowerCase()))});
document.addEventListener('keydown',e=>{
 if(!data)return;const typing=e.target.closest('input,textarea,select,[contenteditable=true]');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!typing&&!$('#dialog').open){e.preventDefault();showFiles();return}if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey||typing||$('#dialog').open)return;
 if(e.key==='Escape'&&$('#context').classList.contains('is-open')){$('#close-context').click();return}if(e.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setTab(e.key==='Home'?'summaries':e.key==='End'?'comments':state.tab==='summaries'?'comments':'summaries');$(`#${state.tab}-tab`).focus();return}if(e.key.toLowerCase()==='j'){e.preventDefault();setLayer(state.layer+1)}if(e.key.toLowerCase()==='k'){e.preventDefault();setLayer(state.layer-1)}if(e.key.toLowerCase()==='z'&&(currentFile()||state.focus)){e.preventDefault();toggleFocus()}
});
async function loadData(){try{const r=await fetch('review-data.json');if(!r.ok)throw Error('Unavailable');data=await r.json();renderScreen();scrollToLine(49,false);const demo=new URLSearchParams(location.search).get('state');if(demo==='loading')loadingDemo();if(demo==='unavailable')unavailableDemo();if(demo==='empty'){state.emptyDemo=true;setTab('comments')}}catch{$('#diff').innerHTML='<div class="unavailable"><h3>The pinned fixture could not load</h3><p>Check the connection and retry. No review state was sent.</p><button class="primary" id="retry-data">Retry</button></div>'}}
loadData();
